import pandas as pd

def calculate_influence(salesperson: pd.DataFrame, customer: pd.DataFrame, sales: pd.DataFrame) -> pd.DataFrame:
    df = salesperson.merge(customer, on='salesperson_id', how='left')
    df = df.merge(sales, on='customer_id', how='left')
    res = df.groupby(['salesperson_id', 'name'], as_index=False)['price'].sum()
    return res.rename(columns={'price': 'total'})
